import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// TILE_DIM should be a multiple of 32 for optimal performance with shared memory
#define TILE_DIM 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    // Global row and column index for the current thread
    int globalRow = blockIdx.y * TILE_DIM + threadIdx.y;
    int globalCol = blockIdx.x * TILE_DIM + threadIdx.x;

    float Cvalue = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_DIM - 1) / TILE_DIM; ++tile) {
        // Load tile of A into shared memory
        int Arow = globalRow;
        int Acol = tile * TILE_DIM + threadIdx.x;
        if (Arow < N && Acol < N) {
            sA[threadIdx.y][threadIdx.x] = A[Arow * N + Acol];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // Load tile of B into shared memory
        int Brow = tile * TILE_DIM + threadIdx.y;
        int Bcol = globalCol;
        if (Brow < N && Bcol < N) {
            sB[threadIdx.y][threadIdx.x] = B[Brow * N + Bcol];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads(); // Synchronize to ensure all shared memory loads are complete

        // Perform dot product using shared memory tiles
        for (int k = 0; k < TILE_DIM; ++k) {
            Cvalue += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads(); // Synchronize before loading next tiles
    }

    // Write result to global memory
    if (globalRow < N && globalCol < N) {
        C[globalRow * N + globalCol] = Cvalue;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch.zeros({N, N}, A.options());

    // Define block and grid dimensions
    dim3 block_size(TILE_DIM, TILE_DIM);
    dim3 num_blocks((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

