    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_DIM - 1) / TILE_DIM; ++tile) {
        // Load tile of A into shared memory (coalesced access)
        int Arow = globalRow;
        int Acol = tile * TILE_DIM + threadIdx.x;
